from taf.ul.auto_commissioning.data_storage.pickle_data import PythonDataStorage
from taf.ul.auto_commissioning.data_storage.json_data import JsonDataStorage
from taf.ul.auto_commissioning.generator.custom_mos_mapping import ManagedObject


class PyDelta:

    def __init__(self, removed, added, changed):
        self.removed = removed
        self.added = added
        self.changed = changed

    def save_to_pickle(self, pkl_addr):
        PythonDataStorage(pkl_addr).save(self)

    def save_to_json(self, json_addr):
        JsonDataStorage(json_addr).save({
            "removed": [mo.translate_to_dict() for mo in self.removed],
            "added": [mo.translate_to_dict() for mo in self.added],
            "changed": [mo.translate_to_dict() for mo in self.changed]
        })

    @classmethod
    def load_from_pickle(cls, pkl_addr):
        return PythonDataStorage(pkl_addr).load()

    @classmethod
    def load_from_json(cls, json_addr):
        data = JsonDataStorage(json_addr).load()
        return PyDelta(
            removed=[ManagedObject.create_from_dict(mo) for mo in data["removed"]],
            added=[ManagedObject.create_from_dict(mo) for mo in data["added"]],
            changed=[ManagedObject.create_from_dict(mo) for mo in data["changed"]])

    def __eq__(self, other):
        return True if self._same_managed_objecs(self.removed, other.removed)\
                    and self._same_managed_objecs(self.added, other.added)\
                    and self._same_managed_objecs(self.changed, other.changed) else False

    def __ne__(self, other):
        return True if not self._same_managed_objecs(self.removed, other.removed)\
                    or not self._same_managed_objecs(self.added, other.added)\
                    or not self._same_managed_objecs(self.changed, other.changed) else False

    def _same_managed_objecs(self, iter1, iter2):
        return True if self._sorted_by_distname(iter1) == self._sorted_by_distname(iter2) else False

    def _sorted_by_distname(self, objs):
        return sorted(objs, key=lambda x: x.dist_name)
